// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        (, uint256 recorded) = c.Acc(actor);
        assertTrue(address(c).balance == recorded);
    }
}
